import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Post","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/post.md","filePath":"03-developer/models/post.md"}`),a={name:`03-developer/models/post.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="post" tabindex="-1">Post <a class="header-anchor" href="#post" aria-label="Permalink to “Post”">​</a></h1><p>The <code>Post</code> model is used to manage posts and the site&#39;s text content. Each post is associated with a group (<code>Group</code>) and a user (<code>User</code>), and supports features such as publishing or saving drafts, counting views, pinning important posts, automatic tables of contents, custom themes, and SEO settings.</p><h2 id="posts-table-structure" tabindex="-1"><code>posts</code> table structure <a class="header-anchor" href="#posts-table-structure" aria-label="Permalink to “posts table structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Post ID</td></tr><tr><td><code>title</code></td><td>TEXT</td><td>No</td><td>Post title</td></tr><tr><td><code>slug</code></td><td>VARCHAR(255)</td><td>No</td><td>Text identifier for the post in the URL; unique</td></tr><tr><td><code>subtitle</code></td><td>TEXT</td><td>No</td><td>Post subtitle</td></tr><tr><td><code>body</code></td><td>LONGTEXT</td><td>No</td><td>Main post content</td></tr><tr><td><code>group_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Post group ID; associated with the <code>groups</code> table</td></tr><tr><td><code>user_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Author ID; associated with the <code>users</code> table</td></tr><tr><td><code>status</code></td><td>TINYINT UNSIGNED</td><td>No</td><td>Post status; <code>0</code> for draft and <code>1</code> for published</td></tr><tr><td><code>view</code></td><td>INT UNSIGNED</td><td>No</td><td>Number of post views</td></tr><tr><td><code>is_pinned</code></td><td>TINYINT(1)</td><td>No</td><td>Indicates whether the post is pinned as important</td></tr><tr><td><code>hash</code></td><td>VARCHAR(14)</td><td>No</td><td>Short post identifier used in short links</td></tr><tr><td><code>like</code></td><td>INT UNSIGNED</td><td>No</td><td>Number of likes</td></tr><tr><td><code>dislike</code></td><td>INT UNSIGNED</td><td>No</td><td>Number of dislikes</td></tr><tr><td><code>icon</code></td><td>VARCHAR(128) NULL</td><td>Yes</td><td>Name of the Remix Icon selected through the Icon Picker</td></tr><tr><td><code>table_of_contents</code></td><td>TINYINT(1)</td><td>No</td><td>Whether the automatic table of contents is enabled</td></tr><tr><td><code>theme</code></td><td>LONGTEXT</td><td>Yes</td><td>JSON data for this post&#39;s custom theme</td></tr><tr><td><code>canonical</code></td><td>TEXT</td><td>Yes</td><td>Canonical URL for SEO</td></tr><tr><td><code>promote</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Field intended for publishing or promoting content on another site; not yet implemented</td></tr><tr><td><code>keyword</code></td><td>TEXT</td><td>Yes</td><td>SEO-related keywords</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Soft deletion time</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Last update time</td></tr><tr><td><code>markups</code></td><td>TEXT</td><td>Yes</td><td>Custom Schema Markup data for the post</td></tr></tbody></table><h2 id="post-status-and-display" tabindex="-1">Post status and display <a class="header-anchor" href="#post-status-and-display" aria-label="Permalink to “Post status and display”">​</a></h2><h3 id="status" tabindex="-1"><code>status</code> <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h3><p>Specifies the post status:</p><ul><li><code>0</code>: Draft</li><li><code>1</code>: Published</li></ul><h3 id="view" tabindex="-1"><code>view</code> <a class="header-anchor" href="#view" aria-label="Permalink to “view”">​</a></h3><p>Stores the number of post views.</p><h3 id="is-pinned" tabindex="-1"><code>is_pinned</code> <a class="header-anchor" href="#is-pinned" aria-label="Permalink to “is_pinned”">​</a></h3><p>Used to identify important, pinned posts, similar to the Sticky Posts feature in WordPress.</p><h3 id="like-and-dislike" tabindex="-1"><code>like</code> and <code>dislike</code> <a class="header-anchor" href="#like-and-dislike" aria-label="Permalink to “like and dislike”">​</a></h3><p>Store the number of likes and dislikes for the post.</p><h3 id="hash" tabindex="-1"><code>hash</code> <a class="header-anchor" href="#hash" aria-label="Permalink to “hash”">​</a></h3><p>A short identifier for the post, currently intended for use in short links. This field is unique in the database.</p><h3 id="icon" tabindex="-1"><code>icon</code> <a class="header-anchor" href="#icon" aria-label="Permalink to “icon”">​</a></h3><p>Stores the name of the Remix Icon selected for the post. The icon is selected through the Icon Picker.</p><h2 id="automatic-table-of-contents" tabindex="-1">Automatic table of contents <a class="header-anchor" href="#automatic-table-of-contents" aria-label="Permalink to “Automatic table of contents”">​</a></h2><h3 id="table-of-contents" tabindex="-1"><code>table_of_contents</code> <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to “table_of_contents”">​</a></h3><p>This field specifies whether the automatic table of contents is enabled for the post.</p><p>The table of contents is generated from HTML headings, from <code>h1</code> through <code>h6</code>.</p><h2 id="custom-post-theme" tabindex="-1">Custom post theme <a class="header-anchor" href="#custom-post-theme" aria-label="Permalink to “Custom post theme”">​</a></h2><h3 id="theme" tabindex="-1"><code>theme</code> <a class="header-anchor" href="#theme" aria-label="Permalink to “theme”">​</a></h3><p>Stores JSON data for this post&#39;s custom theme.</p><p>This feature allows a post to have its own custom theme without necessarily using the site&#39;s general appearance. The custom theme architecture and how its components are loaded are described in the <a href="./part.html">Part</a> document.</p><h2 id="seo-settings" tabindex="-1">SEO settings <a class="header-anchor" href="#seo-settings" aria-label="Permalink to “SEO settings”">​</a></h2><h3 id="canonical" tabindex="-1"><code>canonical</code> <a class="header-anchor" href="#canonical" aria-label="Permalink to “canonical”">​</a></h3><p>Stores the post&#39;s canonical URL to specify its reference URL for search engines.</p><h3 id="keyword" tabindex="-1"><code>keyword</code> <a class="header-anchor" href="#keyword" aria-label="Permalink to “keyword”">​</a></h3><p>Stores keywords related to the post for SEO settings.</p><h3 id="markups" tabindex="-1"><code>markups</code> <a class="header-anchor" href="#markups" aria-label="Permalink to “markups”">​</a></h3><p>Used to store custom Schema Markup for the post. This data can specify the structured markup associated with this post.</p><h2 id="planned-feature-promote" tabindex="-1">Planned feature: <code>promote</code> <a class="header-anchor" href="#planned-feature-promote" aria-label="Permalink to “Planned feature: promote”">​</a></h2><p>The <code>promote</code> field is intended for a feature that will allow a post to be promoted or published on another site, similar to publishing content through mechanisms such as RSS Push, with a link to the original post.</p><p>This idea is also planned for products, but the feature has not yet been implemented in the current project. Therefore, it should not be considered an active system feature.</p><h2 id="database-relationships" tabindex="-1">Database relationships <a class="header-anchor" href="#database-relationships" aria-label="Permalink to “Database relationships”">​</a></h2><ul><li><code>group_id</code> references the <code>groups</code> table, and deleting a group is restricted with <code>ON DELETE RESTRICT</code>.</li><li><code>user_id</code> references the <code>users</code> table, and deleting a user is restricted with <code>ON DELETE RESTRICT</code>.</li><li>The <code>slug</code> and <code>hash</code> fields are each unique.</li><li>The <code>theme</code> field has a <code>CHECK (json_valid(theme))</code> constraint; therefore, any non-<code>NULL</code> value must be valid JSON.</li></ul><h2 id="properties-methods-and-relationships" tabindex="-1">Properties, methods, and relationships <a class="header-anchor" href="#properties-methods-and-relationships" aria-label="Permalink to “Properties, methods, and relationships”">​</a></h2><h3 id="translatability" tabindex="-1">Translatability <a class="header-anchor" href="#translatability" aria-label="Permalink to “Translatability”">​</a></h3><div class="language-php"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $translatable </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;title&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;subtitle&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;body&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>The <code>title</code>, <code>subtitle</code>, and <code>body</code> fields are translatable.</p><h3 id="groups" tabindex="-1"><code>groups()</code> <a class="header-anchor" href="#groups" aria-label="Permalink to “groups()”">​</a></h3><p>Defines a <code>belongsToMany</code> relationship with the <a href="./group.html">Group</a> model. This relationship retrieves the groups associated with the post.</p><p>Note that this relationship uses Laravel&#39;s default pivot table for many-to-many relationships; the pivot table&#39;s name and structure are not specified in the provided code.</p><h3 id="author" tabindex="-1"><code>author()</code> <a class="header-anchor" href="#author" aria-label="Permalink to “author()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <code>User</code> model and returns the post&#39;s author. The foreign key is <code>user_id</code>, and the referenced key is <code>id</code>.</p><h3 id="getroutekeyname" tabindex="-1"><code>getRouteKeyName()</code> <a class="header-anchor" href="#getroutekeyname" aria-label="Permalink to “getRouteKeyName()”">​</a></h3><p>Specifies <code>slug</code> as the key used for Route Model Binding. Therefore, this model uses the post&#39;s text identifier to identify it in a Route.</p><h3 id="markupkeywords" tabindex="-1"><code>markupKeywords()</code> <a class="header-anchor" href="#markupkeywords" aria-label="Permalink to “markupKeywords()”">​</a></h3><p>Provides a list of variables that can be used in Schema Markup. The following items are shown in the provided portion of the method:</p><ul><li><code>app.name</code>: Application name from the <code>app.name</code> setting</li><li><code>title</code>: Post title</li></ul><p>Each item includes a display title and its corresponding value. The complete list of variables depends on the rest of the method&#39;s implementation.</p><h3 id="registermediaconversions-media-media-null" tabindex="-1"><code>registerMediaConversions(?Media $media = null)</code> <a class="header-anchor" href="#registermediaconversions-media-media-null" aria-label="Permalink to “registerMediaConversions(?Media $media = null)”">​</a></h3><p>Registers the image conversions used for post images with Spatie Media Library.</p><ul><li>Conversion name: <code>post-image</code></li><li>Image dimensions are read from the <code>post_thumb</code> setting and the <code>imageSizeConvertValidate()</code> function.</li><li>The image is cropped to the specified dimensions.</li><li>Image optimization and sharpening are applied with <code>sharpen(10)</code>.</li><li>The conversion runs as <code>nonQueued()</code>, meaning it is not added to the processing queue.</li><li>The output format is taken from the <code>optimize</code> setting; if its value is <code>false</code>, <code>webp</code> is selected.</li><li>If the <code>watermark</code> setting is enabled, the <code>public/upload/images/logo.png</code> logo is placed as a watermark at the bottom left of the image. Its size and opacity are read from the application settings.</li></ul><h3 id="imgurl" tabindex="-1"><code>imgUrl()</code> <a class="header-anchor" href="#imgurl" aria-label="Permalink to “imgUrl()”">​</a></h3><p>Returns the URL of the optimized post image. If a media image exists, the URL for the <code>post-image</code> conversion is retrieved from the first media item; otherwise, the URL of the site&#39;s default logo is returned.</p><h3 id="orgurl" tabindex="-1"><code>orgUrl()</code> <a class="header-anchor" href="#orgurl" aria-label="Permalink to “orgUrl()”">​</a></h3><p>Returns the original URL of the post&#39;s first media item without selecting the <code>post-image</code> conversion. If no media item exists, the URL of the site&#39;s default logo is returned.</p><h3 id="spendtime" tabindex="-1"><code>spendTime()</code> <a class="header-anchor" href="#spendtime" aria-label="Permalink to “spendTime()”">​</a></h3><p>Calculates the estimated reading time for the post based on its content.</p><p>First, HTML tags are removed from <code>body</code>. The length of the resulting string is then divided by <code>1350</code> and rounded up to the next integer. Finally, the calculated number is returned with the translatable phrase <code>minute(s)</code>.</p><p>This calculation is based on string length, not an exact word count. Therefore, the resulting reading time is an estimate based on the current implementation.</p><h3 id="comments" tabindex="-1"><code>comments()</code> <a class="header-anchor" href="#comments" aria-label="Permalink to “comments()”">​</a></h3><p>Defines a <code>morphMany</code> relationship with the <a href="./comment.html">Comment</a> model and returns the comments associated with the post.</p><h3 id="approvedcomments" tabindex="-1"><code>approvedComments()</code> <a class="header-anchor" href="#approvedcomments" aria-label="Permalink to “approvedComments()”">​</a></h3><p>In the current implementation, this method also returns the same <code>morphMany</code> relationship with the <code>Comment</code> model.</p><p>The provided code contains no condition that limits the results to approved comments. Therefore, the method&#39;s name does not fully match its current behavior unless an approval filter is applied elsewhere.</p><h3 id="maingroup" tabindex="-1"><code>mainGroup()</code> <a class="header-anchor" href="#maingroup" aria-label="Permalink to “mainGroup()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./group.html">Group</a> model and returns the post&#39;s main group through <code>group_id</code>.</p><p>This relationship differs from <code>groups()</code>: <code>mainGroup()</code> retrieves the main group from the <code>group_id</code> column, whereas <code>groups()</code> is a many-to-many relationship.</p><h3 id="attachs" tabindex="-1"><code>attachs()</code> <a class="header-anchor" href="#attachs" aria-label="Permalink to “attachs()”">​</a></h3><p>Defines a <code>morphMany</code> relationship with the <a href="./attachment.html">Attachment</a> model and returns the files and attachments associated with the post.</p><h3 id="weburl" tabindex="-1"><code>webUrl()</code> <a class="header-anchor" href="#weburl" aria-label="Permalink to “webUrl()”">​</a></h3><p>Generates the post&#39;s public URL using the Route named <code>client.post</code> and the <code>slug</code> value, then applies <code>fixUrlLang()</code> to adjust the URL according to the site&#39;s language logic.</p><h3 id="weburllang-lang" tabindex="-1"><code>webUrlLang($lang)</code> <a class="header-anchor" href="#weburllang-lang" aria-label="Permalink to “webUrlLang($lang)”">​</a></h3><p>Generates the post&#39;s public Route URL and then adds the specified language prefix to the URL by replacing <code>config(&#39;app.url&#39;)</code>.</p><p>The exact behavior of this method depends on the application&#39;s URL structure and the value of <code>$lang</code>.</p><h3 id="markup" tabindex="-1"><code>markup()</code> <a class="header-anchor" href="#markup" aria-label="Permalink to “markup()”">​</a></h3><p>This method is intended to generate Schema Markup for the post. Since the method body was not included in the submitted code, the Schema type and output-generation details cannot be determined from the available information.</p>`,81)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};